import{_ as n,o as t,c as a,a2 as o}from"./chunks/framework.CtQGab4e.js";const i="/teken-tool/handleiding/favicon.svg",m=JSON.parse('{"title":"Handleiding teken-tool","description":"","frontmatter":{"prev":false,"next":false},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function l(s,e,d,p,g,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<p><img src="'+i+'" alt="" class="home-logo"></p><h1 id="handleiding-teken-tool" tabindex="-1">Handleiding teken-tool <a class="header-anchor" href="#handleiding-teken-tool" aria-label="Permalink to &quot;Handleiding teken-tool&quot;">​</a></h1><p>De teken-tool is een notitie-app voor de tablet: vrij tekenen, schrijven, foto&#39;s en plattegronden op een oneindig canvas.</p><p>Van een plattegrond maak je een 3D-model, met de m² per constructie automatisch berekend.</p><h2 id="waar-wil-je-beginnen" tabindex="-1">Waar wil je beginnen? <a class="header-anchor" href="#waar-wil-je-beginnen" aria-label="Permalink to &quot;Waar wil je beginnen?&quot;">​</a></h2><ul><li><strong>Nieuw hier?</strong> Teken <a href="./plattegrond/eerste-plattegrond.html">je eerste plattegrond</a>.</li><li><strong>Wat doet dit knopje?</strong> In <a href="./tool/scherm.html">Het scherm</a> staan alle icoontjes.</li><li><strong>Een specifieke casus tekenen?</strong> Kijk in <a href="./hoe-teken-ik/">Hoe teken ik…?</a>.</li><li><strong>Van tekening naar oppervlaktes?</strong> Zie <a href="./plattegrond/3d-paneel.html">Het 3D-paneel</a>.</li><li><strong>Werkt iets niet?</strong> Zie de <a href="./faq.html">veelgestelde vragen</a>.</li></ul><hr class="ruim"><div class="tip custom-block"><p class="custom-block-title">iPad: open de tool als app</p><p>Tik in Safari op het deelicoon en kies <strong>Zet op beginscherm</strong>. Op je beginscherm staat dan het icoon van de teken-tool. Open je hem daarvandaan, dan opent de app volledig scherm.</p><p>Let op: de app op het beginscherm heeft <strong>eigen opslag</strong>, los van Safari. Notities die je in Safari maakte, zie je daar niet. Zet ze over met <strong>Exporteren als JSON</strong> in Safari en <strong>Importeren</strong> in de app (zie <a href="./tool/opslaan.html">Opslaan</a>). Werk daarna bij voorkeur alleen nog vanuit de app.</p></div>',8)])])}const k=n(r,[["render",l]]);export{m as __pageData,k as default};
